import { describe, it } from "vitest";

describe("MHPCO quote -- base premiums", () => {
  it.todo("empty item list -- premium 5 G (processing fee only)");
  it.todo("single sword, no modifiers -- base premium 100 G");
  it.todo("single amulet, no modifiers -- base premium 60 G");
  it.todo("single staff, no modifiers -- base premium 80 G");
  it.todo("single potion, no modifiers -- base premium 40 G");
  it.todo("single rune (component) -- base premium 25 G");
  it.todo("single moonstone (component) -- base premium 25 G");
  it.todo("policy base premium is the sum of item base premiums -- sword + amulet = 160 G");
});

describe("MHPCO quote -- component building block of 3 alike", () => {
  it.todo("2 runes -- 50 G base premium (no block)");
  it.todo("3 runes -- 60 G base premium (block applies)");
  it.todo("4 runes -- 100 G base premium (no block -- block requires exactly 3)");
  it.todo("7 runes -- 175 G base premium (no block -- block requires exactly 3)");
  it.todo(
    "alike means the same type: 2 runes + 1 moonstone -- 75 G base premium (no block, different types)",
  );
  it.todo(
    "alike blocks form per type: 3 runes + 3 moonstones -- 120 G base premium (two separate blocks)",
  );
});

describe("MHPCO quote -- item-specific modifiers", () => {
  it.todo("cursed sword -- 50 % risk surcharge on that item's base premium (100 G -> 150 G)");
  it.todo("sword with enchantment 5 -- 30 % high-enchantment surcharge applies (threshold is >= 5)");
  it.todo("sword with enchantment 4 -- no high-enchantment surcharge");
  it.todo(
    "cursed sword with enchantment 5 -- both surcharges apply, each on the item base premium (100 + 50 + 30)",
  );
  it.todo(
    "item-specific modifiers apply only to the affected item: cursed sword + plain amulet -- 160 G base + 50 G curse = 210 G before policy modifiers and fee",
  );
});

describe("MHPCO quote -- policy-wide modifiers", () => {
  it.todo("customer with 2 years with MHPCO -- 20 % loyalty discount applies (threshold is >= 2)");
  it.todo("customer with 1 year with MHPCO -- no loyalty discount");
  it.todo("each quoted item carries a 10 % initial assessment surcharge for first insurance");
  it.todo("second and later contracts receive a 15 % follow-up discount on the policy base premium");
  it.todo("first contract receives no follow-up discount");
  it.todo("a 5 G processing fee is added at the very end of every premium");
});

describe("MHPCO quote -- rounding in the MHPCO's favor", () => {
  it.todo("premium of 197.5 G rounds up to 198 G");
  it.todo("intermediate amounts are kept as fractions -- only the final premium is rounded");
});

describe("MHPCO quote -- integration examples", () => {
  it.todo(
    "newcomer (0 years, first contract) with a cursed sword -- premium 165 G (100 base + 50 curse + 10 first insurance + 5 fee)",
  );
  it.todo(
    "long-standing customer (3 years) second quote, cursed sword enchantment 7 -- premium 160 G (100 + 50 + 30 - 20 loyalty + 10 first insurance - 15 follow-up + 5 fee)",
  );
});

describe("MHPCO quote -- rejections", () => {
  it.todo(
    "quote with an unknown item type (e.g. broomstick) -- throws an Error (chosen reading: the domain signals rejection by throwing; the spec fixes no error type or message)",
  );
});

describe("MHPCO policy -- insurance sum and cap", () => {
  it.todo("a sword -- insurance sum 1000 G, cap 2000 G (twice the insurance sum)");
  it.todo("sword + amulet -- insurance sum 1600 G, cap 3200 G");
  it.todo("two swords -- insurance sum 2000 G, cap 4000 G");
  it.todo(
    "sword + 3 runes (a block) -- insurance sum 1750 G; the block discount affects the premium only",
  );
  it.todo(
    "cursed sword -- cap 2000 G based on the unmodified insurance value; premium modifiers do not raise the cap",
  );
});

describe("MHPCO claim -- standard reimbursement and deductible", () => {
  it.todo("regular sword (steel, enchantment 3), damage 500 G -- payout 400 G (500 - 100 deductible)");
  it.todo(
    "rune (no enchantment level, no material), damage 200 G -- payout 100 G (no special clause applies)",
  );
  it.todo("the 100 G deductible applies once per damaged item");
});

describe("MHPCO claim -- special clauses", () => {
  it.todo("steel sword, enchantment 9, damage 1000 G -- payout 400 G (50 % clause first, then deductible)");
  it.todo("dragon-material sword, enchantment 5, damage 800 G -- payout 700 G (full reimbursement, then deductible)");
  it.todo(
    "dragon-material sword, enchantment 8, damage 1000 G -- payout 400 G (high-enchantment clause applies at the threshold, then deductible)",
  );
  it.todo(
    "dragon-material sword, enchantment 9, damage 1000 G -- payout 400 G (both clauses apply; the 50 % rule wins, then deductible)",
  );
});

describe("MHPCO claim -- multi-item incidents", () => {
  it.todo(
    "dragon attack damages sword (500 G) and amulet (300 G) -- payout 600 G (deductible once per damaged item)",
  );
  it.todo(
    "two swords insured, both damaged -- each damages entry is a separate damage with its own deductible",
  );
});

describe("MHPCO claim -- cap exhaustion across claims", () => {
  it.todo("sword insured (cap 2000 G), first claim of 1500 G -- payout 1400 G, remaining cap 600 G");
  it.todo(
    "second claim of 1500 G on the same policy -- payout 600 G, remaining cap 0 G (desired 1400 G reduced to remaining cap)",
  );
});

describe("MHPCO claim -- rounding in the MHPCO's favor", () => {
  it.todo("payout of 350.5 G rounds down to 350 G");
});

describe("MHPCO claim -- rejections", () => {
  it.todo(
    "damage to an item not part of the policy (amulet damaged, only a sword insured) -- throws an Error (chosen reading: rejection is signalled by throwing)",
  );
  it.todo("damage entry with an unknown item type -- throws an Error");
  it.todo(
    "more damage entries of a type than the policy covers (two sword damages, one sword insured) -- throws an Error; the whole claim is rejected",
  );
  it.todo("damage entry with a negative amount (-200) -- throws an Error");
});

describe("claim-office CLI", () => {
  it.todo(
    "reads a scenario from stdin and writes {results} to stdout with one result per step, in order",
  );
  it.todo("quote step result contains premium as an integer");
  it.todo("claim step result contains payout and remainingCap as integers");
  it.todo("a claim step refers to its policy by the zero-based index of the quote step");
  it.todo(
    "schema example: 5-year customer, amulet quote then 200 G amulet claim -- results match the documented shape",
  );
  it.todo(
    "unknown item type in a quote -- exits non-zero, writes an error description to stderr, writes no results to stdout",
  );
  it.todo("claim against an item not in the policy -- exits non-zero and writes an error description to stderr");
  it.todo("claim with a negative damage amount -- exits non-zero and writes an error description to stderr");
});

