export function quote(customer: Customer, items: Item[]): number {
  const policyBasePremium = items.reduce(
    (total, item) => total + basePremiumFor(item),
    0,
  );
  return policyBasePremium + PROCESSING_FEE;
}

function basePremiumFor(item: Item): number {
  if (isComponent(item)) {
    return COMPONENT_BASE_PREMIUM;
  }
  return MAIN_ITEM_BASE_PREMIUMS[item.type];
}

