  it.todo(
    "damage to an item not part of the policy (amulet damaged, only a sword insured) -- throws an Error (chosen reading: rejection is signalled by throwing)",
  );
  it.todo("damage entry with an unknown item type -- throws an Error");
  it.todo(
    "more damage entries of a type than the policy covers (two sword damages, one sword insured) -- throws an Error; the whole claim is rejected",
  );
  it.todo("damage entry with a negative amount (-200) -- throws an Error");
});

describe("claim-office CLI", () => {
  it.todo(
    "reads a scenario from stdin and writes {results} to stdout with one result per step, in order",
  );
  it.todo("quote step result contains premium as an integer");
  it.todo("claim step result contains payout and remainingCap as integers");
  it.todo("a claim step refers to its policy by the zero-based index of the quote step");
  it.todo(
    "schema example: 5-year customer, amulet quote then 200 G amulet claim -- results match the documented shape",
  );
  it.todo(
    "unknown item type in a quote -- exits non-zero, writes an error description to stderr, writes no results to stdout",
  );
  it.todo("claim against an item not in the policy -- exits non-zero and writes an error description to stderr");
  it.todo("claim with a negative damage amount -- exits non-zero and writes an error description to stderr");
});

