  const mainItems = items.filter((item) => !isComponent(item));
  const components = items.filter(isComponent);

  const mainItemsPremium = mainItems.reduce(
    (total, item) => total + itemPremium(item),
    0,
  );
  const policyBasePremium = mainItemsPremium + componentsBasePremium(components);
  return policyBasePremium + policyModifiers(customer, policyBasePremium) + PROCESSING_FEE;
}

function policyModifiers(customer: Customer, policyBasePremium: number): number {
  if (isLongStandingCustomer(customer)) {
    return -policyBasePremium * LOYALTY_DISCOUNT_RATE;
  }
  return 0;
}

